// === Tab: mySketch ===
var particlesQ = 1024;
var c = 0;

var x = new Array(particlesQ);
var y = new Array(particlesQ);
var vx = new Array(particlesQ);
var vy = new Array(particlesQ);

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowWidth, windowHeight);
  background(255);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {
	for (var a = 0; a < c; a++) {
		var ax = 0, ay = 0;

		for (var b = 0; b < c; b++) {
			if (a != b) {
				dx = x[a] - x[b];
				dy = y[a] - y[b];

				var d = sqrt(dx*dx + dy*dy);
				if (d < 1) d = 1;

				var common = cos(d) / d;

				ax += common * dx;
				ay += common * dy;
			}
		}

		vx[a] += ax * 0.01;
		vy[a] += ay * 0.01;
	}

	for (var i = 0; i < c; i++) {
		x[i] += vx[i];
		y[i] += vy[i];

		set(x[i], y[i], 0);
	}

	updatePixels();
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function addNewParticle() {
	x[c] = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	y[c] = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	vx[c] = 0;
	vy[c] = 0;

	c++;
	if (c >= particlesQ) c = 0;
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseClicked() {
	addNewParticle();
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseDragged() {
	addNewParticle();
}

